//! Marge's radio lines, generated from the browser's tables
//! (src/js/04-dispatcher-radio.js and the fixed lines it passes at call
//! sites) by native/tools/gen_lines.cjs. Do not edit by hand.

use cj_sim::events::Radio;

/// The stock lines for a radio key, as (shown, spoken). Keys whose lines
/// are always built by the simulation (with this moment's numbers) have none.
pub fn lines(key: Radio) -> &'static [(&'static str, &'static str)] {
    match key {
        Radio::Start => &[("Morning, hotshot. Five minutes on the clock. Bring me something worth the fuel.", "Morning, hotshot. Make it worth the fuel."), ("Shift is live, kiddo. Remember, the tug is collateral. So are you.", "Shift is live. You are collateral."), ("Coffee is cold, my knees hurt, and you are on the clock. Go make money.", "Coffee is cold. Go make money.")],
        Radio::Hook => &[("Hooked. Mind the swing.", "Hooked."), ("That is on the line. Try not to lose it this time.", "Do not lose it."), ("Winch is holding. For now.", "Holding. For now.")],
        Radio::Heavy => &[("You are towing a small moon. Turning is a suggestion now.", "Small moon. Good luck turning."), ("Engines are complaining. Join the club.", "Join the club.")],
        Radio::Maxed => &[("Winch is full, sugar. Bank something or cut something.", "Winch is full, sugar.")],
        Radio::Reactor => &[("You hooked a reactor core. Do not shoot the reactor core.", "Do not shoot the reactor."), ("Reactor on the line. One hard bump and it blows. Fly like your grandmother. Not mine. Mine was a menace.", "Reactor. Fly gentle.")],
        Radio::Engine => &[("Engine block. Seven tonnes of bad decisions waiting to happen.", "Seven tonnes of bad decisions.")],
        Radio::Jumper => &[("Claim jumper on scope. They want your haul. Rude.", "Claim jumper. Rude."), ("Pink contact inbound. Rival crew. They are not here to make friends.", "Pink contact. Not friendly.")],
        Radio::SentriesRogue => &[("Tug is down, and your sentries just lost their link. They are shooting at everything now. Including you, hotshot.", "Your sentries went rogue. Everything is a target.")],
        Radio::RogueDown => &[("Rogue sentry down. It dropped its core. Careful: those bite, and they go off if you bang them around.", "Rogue down. Mind the core.")],
        Radio::Latched => &[("They have a line on your cargo. Shoot them, or swing something heavy at their face.", "Swing something at them.")],
        Radio::Severed => &[("They cut your line. That was our money, hotshot.", "That was our money."), ("Line severed. Go get it back. I will wait. I always wait.", "Go get it back.")],
        Radio::Escaped => &[("And it is gone. I am logging that as tuition.", "Gone. Tuition."), ("They got away with it. Insurance says that was your fault. So do I.", "Your fault. So I hear.")],
        Radio::Crab => &[("Crab on your cable. Yank the line hard and shake it off.", "Crab. Yank the line."), ("Something is crawling up your tow line. Give it a good jerk.", "Something is crawling. Jerk it.")],
        Radio::CrabHull => &[("Crab on the hull. Spin the tug and throw it off, or limp home to the bay.", "Spin it off, kiddo.")],
        Radio::CrabOff => &[("Crab overboard. Nice spin. Do not let it go to your head.", "Crab overboard.")],
        Radio::Bank => &[("Banked.", "Banked."), ("Bay crew says thanks. They are lying, but they said it.", "Thanks. They are lying."), ("Logged. The loan officer almost smiled.", "Loan officer almost smiled."), ("Into the bay it goes. Slowly. Like my pension.", "Slowly. Like my pension.")],
        Radio::BankBig => &[("Now that pays the interest. Some of it.", "Some of the interest."), ("Well, look at you. I might even approve your lunch break.", "Well, look at you.")],
        Radio::HullLow => &[("Hull is under thirty percent. Insurance already said no.", "Insurance said no.")],
        Radio::Dead => &[("Tug is down. The deductible comes out of your pay. Again. Respawning at the bay.", "Again. Coming out of your pay.")],
        Radio::Refinery => &[("Sensor ping. The old Kessler ore works is drifting through. Nobody ever cracked that vault. Nobody ever had your nerve, or your debt.", "Kessler refinery. Vault is still full."), ("Big contact. The Kessler refinery. Vault is still sealed, and still full. Do not get greedy. Who am I kidding.", "Big contact. Do not get greedy.")],
        Radio::RefineryHint => &[("There are mining charges floating by the station. Tow them into the three sockets around the vault. Gently, hon.", "Charges in the sockets. Gently, hon.")],
        Radio::Drones => &[("Security drones are waking up. The station still thinks it is on payroll. Must be nice.", "Security is waking up."), ("Station security is online. Mind those charges. One hit and you are a postcard.", "Mind the charges.")],
        Radio::Armed => &[("All three seated. Five seconds. Get clear of the vault.", "Five seconds. Get clear.")],
        Radio::Vault => &[("Vault is open. That is a fortune in refined ore. Grab it and go.", "Vault is open. Grab it and go.")],
        Radio::Jaws => &[("Uh. The jaws are moving. It is eating the field. Do not get eaten. I am not training a replacement.", "It is eating the field."), ("Processing jaws are awake. It is pulling everything in. Including you, genius.", "Including you, genius.")],
        Radio::JawsShip => &[("You are in the jaws. Full thrust, or cut the load. Now.", "Thrust, or cut it.")],
        Radio::AteCargo => &[("It ate your cargo. That station owes us money now. Good luck collecting.", "It ate your cargo.")],
        Radio::Miners => &[("Heads up. Automated mining drones are still working the old Kessler contract. They cut rock and fling it everywhere. Like my ex.", "Mining drones. Flying rock."), ("Mining drones on scope. They do not care what is in the way. Their ore spills are free money, though.", "Miners. Free ore, flying rock.")],
        Radio::Storm => &[("Debris storm by the miners. Those pebbles are moving fast.", "Debris storm."), ("You are in their blast zone. Fast rock incoming. Duck. Figuratively.", "Fast rock. Duck.")],
        Radio::MinerAngry => &[("You shot a miner. Now it is drilling you. Shocking.", "Now it is drilling you."), ("That miner is pointing its cutter at you. Back off, or finish the job.", "Back off, or finish it.")],
        Radio::MinerKill => &[("Miner down. Its ore hopper just burst open.", "Miner down. Grab the ore."), ("Scrapped a miner. Grab the ore before somebody else does.", "Grab the ore.")],
        Radio::Collector => &[("Debt collector on scope. They do not want the cargo. They want the tug.", "They want the tug."), ("Kessler Mutual Recovery is here. And our payment is not even late. Yet.", "Not even late. Yet.")],
        Radio::Netted => &[("You are netted. Hard left, hard right, tear it. Or shoot that thing.", "Tear it, kiddo."), ("They got a net on you. Wiggle out before they tow you off the field.", "Wiggle out.")],
        Radio::NetFree => &[("Net is torn. Now get away from that man.", "Loose. Now run."), ("You are loose. Do not let them line up another shot, sugar.", "Do not get caught again, sugar.")],
        Radio::CollectorKill => &[("Collector down. Legally, I never saw that.", "I never saw that."), ("Scrapped a repo man. That plating is worth something. Unlike him.", "Repo man down.")],
        Radio::Greedy => &[("That collector just went greedy. They are not here for your payment anymore. They want your haul.", "Greedy bastards want your haul.")],
        Radio::CollectorLeaves => &[("Collector is leaving. Your numbers check out, for once.", "Your numbers check out.")],
        Radio::NetEdge => &[("They are almost at the edge with you. Break free. Now.", "Break free. Now.")],
        Radio::FatCable => &[("That is a fat cable. Kessler Mutual noticed. Collector inbound, and they will take the load if they catch you.", "Fat cable. Get it home."), ("You are hauling a fortune, and the bank can smell it. Collector on the way. Get it home.", "The bank smells money.")],
        Radio::DroneKill => &[("Drone down. Kessler Security can send me the bill. I will lose it.", "Drone down.")],
        Radio::RivalsAnnoyed => &[("You keep scrapping their people. The rival crews are annoyed now. They will shoot while they steal.", "The rivals are annoyed.")],
        Radio::RivalsHostile => &[("The rival crews have a grudge, kiddo. Some of them are coming for you now, not the cargo.", "Some are coming for you now.")],
        Radio::RivalsVendetta => &[("Congratulations. It is a vendetta. They hunt in pairs now. I am updating your obituary.", "It is a vendetta.")],
        Radio::Hunter => &[("Rival inbound, and that one is not here for cargo. It is here for you.", "That one is here for you."), ("Hunter on scope. Somebody holds a grudge, hotshot.", "Somebody holds a grudge.")],
        Radio::WantedMore => &[("Another collector? Your wanted level just went up again. The sheriff reads the same reports I do.", "Wanted level is up again.")],
        Radio::SheriffPatrol => &[("Sheriff patrol in the field. Keep your nose clean, for once.", "Sheriff patrol. Behave.")],
        Radio::SheriffWanted => &[("Sheriff patrol inbound, and you are wanted. Keep your distance.", "Keep your distance.")],
        Radio::Pursuit => &[("The sheriff spotted you. Run, or get cuffed. Do not let him get close.", "Run, or get cuffed."), ("Lights and sirens, kiddo. He is on you. Keep moving.", "He is on you. Move.")],
        Radio::LostSheriff => &[("You lost him. For now. He will be back, they always are.", "You lost him. For now.")],
        Radio::SheriffShotAt => &[("Watch your fire, hotshot. That is the sheriff. Hit him all you like, but if he goes down, you are wanted.", "Watch your fire. That is the sheriff.")],
        Radio::Reinforcements => &[("More law inbound. They are bringing friends.", "More law inbound."), ("Backup is on the way, and it is not yours.", "Backup is on the way.")],
        Radio::Swat => &[("Five stars. That is the Galactic SWAT team. Live rounds, hotshot. Run. Very. Fast.", "Galactic SWAT. Run.")],
        Radio::Shakedown => &[("The sheriff is shaking you down. No warrant, no reason, he just wants your cargo. Run, or lose it.", "Shakedown. He wants your cargo.")],
        Radio::SheriffKill => &[("You shot down the sheriff. Two more stars. I am not bailing you out.", "I am not bailing you out.")],
        Radio::ShieldDown => &[("Shields are down. Hull is next, hotshot.", "Hull is next, hotshot."), ("There go your shields. Try not getting hit. Novel idea.", "Try not getting hit.")],
        Radio::MissilesLive => &[("Missile rack is live. It shoots first and never asks.", "Missiles are live.")],
        Radio::Overheat => &[("Heat sink is cooked. Guns and thrusters are locked until it cools. Like you should be.", "Cool it, hotshot."), ("You are overheating. Ease off the trigger, hotshot.", "Ease off.")],
        Radio::Grind => &[("Ground it into slugs. Accounting just wept.", "Accounting just wept."), ("Grinder fed. Sale value, zero. Ammo, plenty. I hate it here.", "I hate it here.")],
        Radio::GrindReactor => &[("You put a reactor in the grinder? A reactor. In the grinder.", "A reactor. In the grinder.")],
        Radio::Scooped => &[("Scoop caught something. Free money, probably.", "Free money.")],
        Radio::Kill => &[("Jumper scrapped. Their parts spend like anybody else's.", "Jumper scrapped."), ("One less pink dot. Grab what fell off.", "One less pink dot.")],
        Radio::Smash => &[("You hit him with an engine. That is going in the newsletter.", "Newsletter material."), ("Cargo-based diplomacy. I approve.", "I approve.")],
        Radio::Boom => &[("That was a reactor. Was. Past tense.", "Was a reactor."), ("Reactor blew. Count your fingers. Then count the cargo.", "Count your fingers.")],
        Radio::Cut => &[("Cut loose. Your cargo, your call. Your mistake.", "Your mistake.")],
        Radio::Minute => &[("One minute left. Bring it home.", "Bring it home.")],
        Radio::TenSec => &[("Ten seconds. Bay doors are closing.", "Doors are closing.")],
        Radio::NewWreck => &[("New derelict drifting into the field. Fresh pickings.", "Fresh wreck.")],
        Radio::Repair => &[("Bay crew is patching you up. Hold still, you are not that interesting.", "Hold still.")],
        Radio::CoreZap => &[("That core is still angry. It will bite you every so often until it is in the bay.", "That core bites. Get it home.")],
        Radio::EngineOverheat => &[("You cooked the engine, hotshot. Six seconds of crawling while it cools. Ease off the burners.", "You cooked the engine.")],
        Radio::JawsWrecked => &[("You broke the jaws. Somebody at Kessler is going to cry about that. It won't be me.", "You broke the jaws.")],
        Radio::EscortDone => &[("Hauler is docked. Not a scratch on it. Well, a few scratches. Nobody is counting.", "Hauler docked. Nice work.")],
        Radio::EscortLow => &[("The hauler is coming apart, hon. Get those crews off it.", "Hauler is coming apart.")],
        Radio::EscortLost => &[("We lost the hauler. That is going to be an awkward phone call.", "We lost the hauler.")],
        Radio::IonClear => &[("Ion storm has passed. Shields are coming back up. Slowly. Like everything else around here.", "Storm passed. Shields coming back.")],
        Radio::IonStorm => &[("Ion storm rolling through. Your shields are gone until it passes. Fly like you mean it.", "Ion storm. Shields are down.")],
        Radio::Derelict => &[("Derelict freighter on scope. Hold full of salvage and nobody aboard. Every crew in the belt heard that too.", "Derelict freighter. Everyone heard.")],
        Radio::Scatter => &[("Ha. Look at them run. Nobody wants to be next under that cargo.", "Look at them run.")],
        Radio::HoldOpen => &[("Hold is open. Ingots, an engine, maybe a reactor. Somebody locked that up for a reason. Take it anyway.", "Hold is open. Take it all.")],
        Radio::HoldSealed => &[("That hold is sealed tight, hotshot. There is a keycard floating around out there. Tow it in.", "Hold is sealed. Find the keycard.")],
        Radio::Sanctuary => &[("Carrier's private property, hotshot. The law can't touch you in here. Your record's clean. For now.", "Law can't touch you in here. Record's clean.")],
        Radio::Escort => &[("Freight hauler inbound, headed for our bay, and every crew in the belt can see it. Keep them off it, hotshot.", "Hauler inbound. Keep them off it.")],
        _ => &[],
    }
}

/// The cockpit warning callout said before Marge's line on urgent keys.
pub fn callout(key: Radio) -> Option<&'static str> {
    Some(match key {
        Radio::IonStorm => "Warning. Ion storm.",
        Radio::Boss => "Warning. Bounty target.",
        Radio::Derelict => "Contact. Derelict freighter.",
        Radio::SentriesRogue => "Warning. Rogue drones.",
        Radio::HullLow => "Warning. Hull integrity.",
        Radio::Dead => "Hull failure.",
        Radio::CrabHull => "Warning. Hull breach.",
        Radio::Netted => "Warning. Net. Net.",
        Radio::NetEdge => "Warning. Field boundary.",
        Radio::Collector => "Caution. Debt collector.",
        Radio::Greedy => "Warning. Hostile collector.",
        Radio::FatCable => "Caution. Debt collector.",
        Radio::LowWallet => "Caution. Payment shortfall.",
        Radio::Confiscated => "Cargo confiscated.",
        Radio::Latched => "Caution. Cargo tether.",
        Radio::Severed => "Cable severed.",
        Radio::Jaws => "Warning. Proximity.",
        Radio::JawsShip => "Pull out. Pull out.",
        Radio::Armed => "Charges armed.",
        Radio::Overheat => "Overheat. Overheat.",
        Radio::Minute => "One minute.",
        Radio::TenSec => "Ten seconds.",
        Radio::ShieldDown => "Shields down.",
        Radio::Pursuit => "Warning. Law enforcement.",
        Radio::SheriffWanted => "Caution. Sheriff patrol.",
        Radio::Hunter => "Caution. Hostile contact.",
        Radio::Swat => "Warning. Warning. SWAT.",
        Radio::Reinforcements => "Caution. Additional units.",
        Radio::Shakedown => "Warning. Law enforcement.",
        Radio::Arrested => "Arrested.",
        _ => return None,
    })
}

/// What Marge mutters before a routine line, about a third of the time.
pub const ASIDES: [&str; 8] = [
    "Hmph.",
    "Mm.",
    "Oh, sugar.",
    "Lord.",
    "Well.",
    "Kiddo.",
    "Sweetheart.",
    "Uh-huh.",
];
